CREATE FUNCTION nb_commandes(p_id_client INT)
RETURNS INT
DETERMINISTIC
BEGIN
    DECLARE total INT;
    SELECT COUNT(*) INTO total FROM COMMANDE WHERE id_client = p_id_client;
    RETURN total;
END;
