CREATE FUNCTION verifier_stock(
    p_id_produit INT,
    p_quantite_demandee INT
)
RETURNS BOOLEAN
READS SQL DATA
BEGIN
    DECLARE stock_actuel INT;

    -- Vérifier que la quantité est positive
    IF p_quantite_demandee <= 0 THEN
        RETURN FALSE;
    END IF;

    -- Récupérer le stock avec gestion de l'absence du produit
    SELECT stock INTO stock_actuel FROM PRODUIT WHERE id = p_id_produit;

    -- Gérer le cas où le produit n'existe pas
    IF stock_actuel IS NULL THEN
        RETURN FALSE;
    END IF;

    RETURN stock_actuel >= p_quantite_demandee;
END;
```
